'use strict';
// assets/senkon/ornek-pafta.svg: the sample sheet on /tasarim/, generated by tools/make-pafta.js from the hall model.
// The generator is the source: the committed file must equal build(). The sheet must say it is a sample and must
// never name a real project.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { planes, elevation, build } = require('../tools/make-pafta.js');

const FILE = path.join(__dirname, '..', 'assets', 'senkon', 'ornek-pafta.svg');
const read = () => fs.readFileSync(FILE, 'utf8');

test('the sheet file exists and is an A3 sheet in millimetres', () => {
  assert.ok(fs.existsSync(FILE));
  const svg = read();
  assert.match(svg, /viewBox="0 0 420 297"/);
  assert.match(svg, /<svg[^>]*class="pafta-svg"/);
  assert.equal((svg.match(/class="pafta-sheet"/g) || []).length, 1);
});

test('the title block says it is a sample sheet of Senkon Mühendislik', () => {
  const svg = read();
  for (const s of ['ÖRNEK PAFTA', 'Senkon Mühendislik', 'gerçek bir projeye ait değildir', 'Ö-01']) assert.ok(svg.includes(s), s);
  assert.ok(svg.includes('Çizim standardını göstermek amacıyla hazırlanmıştır; gerçek bir projeye ait değildir.'));
});

test('the sheet is self-contained line work and text', () => {
  const svg = read();
  assert.doesNotMatch(svg, /<image/);
  assert.doesNotMatch(svg, /<script/);
  assert.doesNotMatch(svg, /href="http/);
  assert.ok(Buffer.byteLength(svg) < 150 * 1024, 'under 150 KB');
});

test('the sheet names no real project', () => {
  const svg = read().toLocaleLowerCase('tr');
  for (const name of ['Esenboğa', 'Koç', 'Antalya', 'Malatya', 'Alfraganus', 'Vem', 'Biem', 'Karmall', 'Tuzla', 'Amazon']) {
    assert.ok(!svg.includes(name.toLocaleLowerCase('tr')), name);
  }
});

test('the committed file is what the generator writes', () => {
  assert.equal(read(), build());
});

test('planes() lists constant-z planes, most members first', () => {
  const members = [
    [0, 0, 1, 1, 0, 1, 0.2], [0, 0, 1, 0, 1, 1, 0.2],
    [0, 0, 2, 1, 1, 2, 0.2],
    [0, 0, 0, 0, 0, 5, 0.2],               // runs along z: in no plane
  ];
  assert.deepEqual(planes(members), [{ z: 1, count: 2 }, { z: 2, count: 1 }]);
});

test('elevation() gives the plane members in metres and a box around them', () => {
  const members = [
    [0, -35, 1, 0, 3, 1, 0.7], [0, 3, 1, 10, 4, 1, 0.3],
    [5, 0, 2, 5, 9, 2, 0.2],               // another plane
  ];
  const { lines, box } = elevation(members, 1);
  assert.deepEqual(lines, [[0, -35, 0, 3, 0.7], [0, 3, 10, 4, 0.3]]);
  assert.deepEqual(box, [0, -35, 10, 4]);
  for (const [x1, y1, x2, y2] of lines) {
    assert.ok(x1 >= box[0] && x2 <= box[2] && Math.min(y1, y2) >= box[1] && Math.max(y1, y2) <= box[3]);
  }
});
